//! Basic NEC IR receiver demo.
//!
//! Wiring:
//! - IR receiver data output -> GPIO0
//! - IR receiver VCC -> 3.3V
//! - IR receiver GND -> GND

#![no_std]
#![no_main]

use core::convert::Infallible;
use embassy_executor::Spawner;
use esp_backtrace as _;
use log::info;

use device_envoy_esp::{
    init_and_start, ir,
    ir::{Ir as _, IrEvent},
    Result,
};

esp_bootloader_esp_idf::esp_app_desc!();

ir! {
    IrBoard {
        pin: GPIO0
    }
}

#[esp_rtos::main]
async fn main(spawner: Spawner) -> ! {
    let err = inner_main(spawner).await.unwrap_err();
    panic!("{err:?}");
}

async fn inner_main(spawner: Spawner) -> Result<Infallible> {
    init_and_start!(p, rmt80: rmt80, mode: rmt_mode::Async);
    esp_println::logger::init_logger(log::LevelFilter::Info);
    info!("ir example started: listening for IR input");

    let channel_creator = rmt80.channel2;
    let ir_board = IrBoard::new(p.GPIO0, channel_creator, spawner)?;

    loop {
        let IrEvent::Press { addr, cmd } = ir_board.wait_for_press().await;
        info!("IR press: addr=0x{:04X}, cmd=0x{:02X}", addr, cmd);
    }
}